// Parametric Flanged Shaft Hub (mm)
$fn = 48;

flange_r = 32;
flange_h = 6;
boss_r = 16;
boss_h = 18;
bore_r = 8;
bolt_circle_r = 24;
bolt_hole_r = 2.6;
bolt_count = 6;

module flanged_hub() {
  difference() {
    union() {
      cylinder(r = flange_r, h = flange_h);
      cylinder(r = boss_r, h = boss_h);
    }
    translate([0, 0, -1])
      cylinder(r = bore_r, h = boss_h + 2);
    for (i = [0 : bolt_count - 1]) {
      angle = i * 360 / bolt_count;
      rotate([0, 0, angle])
        translate([bolt_circle_r, 0, -1])
          cylinder(r = bolt_hole_r, h = flange_h + 2);
    }
  }
}

flanged_hub();

// Parametric Metric Spur Gear Generator (mm)
$fn = 36;

module_m = 2.0;
teeth = 24;
face_width = 10.0;
bore_dia = 10.0;
keyway_w = 3.0;
keyway_d = 1.5;

function pitch_radius(m, z) = (m * z) / 2.0;
function root_radius(m, z) = pitch_radius(m, z) - 1.25 * m;

module spur_gear(m = 2.0, z = 24, width = 10.0, bore = 10.0) {
  r_pitch = pitch_radius(m, z);
  r_root = root_radius(m, z);
  tooth_h = 2.25 * m;
  tooth_w = 1.45 * m;

  difference() {
    union() {
      cylinder(r = r_root, h = width);
      for (i = [0 : z - 1]) {
        rotate([0, 0, i * 360 / z])
          translate([r_root - 0.3, -tooth_w / 2, 0])
            cube([tooth_h + 0.3, tooth_w, width]);
      }
    }
    translate([0, 0, -1])
      cylinder(r = bore / 2, h = width + 2);
    translate([bore / 2 - 0.5, -keyway_w / 2, -1])
      cube([keyway_d + 0.5, keyway_w, width + 2]);
  }
}

spur_gear(m = module_m, z = teeth, width = face_width, bore = bore_dia);

// Finned Power-Electronics Heatsink Enclosure (mm)
$fn = 32;

box_len = 120;
box_wid = 80;
box_h = 34;
wall_t = 4;
fin_count = 11;
fin_t = 2.5;
fin_h = 12;
boss_r = 4.5;
screw_r = 1.7;

function fin_pitch(total_w, n, t) = (total_w - t) / (n - 1);

module heatsink_enclosure() {
  pitch = fin_pitch(box_wid, fin_count, fin_t);
  difference() {
    union() {
      cube([box_len, box_wid, box_h]);
      for (i = [0 : fin_count - 1]) {
        translate([0, i * pitch, box_h])
          cube([box_len, fin_t, fin_h]);
      }
    }
    translate([wall_t, wall_t, -1])
      cube([box_len - 2 * wall_t, box_wid - 2 * wall_t, box_h - wall_t + 1]);
  }

  for (x = [wall_t + boss_r, box_len - wall_t - boss_r]) {
    for (y = [wall_t + boss_r, box_wid - wall_t - boss_r]) {
      difference() {
        translate([x, y, 0])
          cylinder(r = boss_r, h = box_h - wall_t);
        translate([x, y, -1])
          cylinder(r = screw_r, h = box_h);
      }
    }
  }
}

heatsink_enclosure();

// Articulated 3-DOF Industrial Robotic Arm (mm)
$fn = 36;

base_angle = 25;
shoulder_angle = 35;
elbow_angle = -45;
link1_len = 160;
link2_len = 130;

module arm_link(length, width, thickness) {
  difference() {
    union() {
      cylinder(r = width / 2, h = thickness);
      translate([0, -width / 2, 0])
        cube([length, width, thickness]);
      translate([length, 0, 0])
        cylinder(r = width / 2, h = thickness);
    }
    translate([0, 0, -1])
      cylinder(r = width * 0.25, h = thickness + 2);
    translate([length, 0, -1])
      cylinder(r = width * 0.25, h = thickness + 2);
  }
}

module parallel_gripper() {
  cube([28, 36, 16], center = true);
  translate([24, 12, 0])
    cube([26, 6, 12], center = true);
  translate([24, -12, 0])
    cube([26, 6, 12], center = true);
}

module robot_arm() {
  cylinder(r = 55, h = 20);
  translate([0, 0, 20])
    rotate([0, 0, base_angle]) {
      cylinder(r = 32, h = 45);
      translate([0, 0, 45])
        rotate([90, -shoulder_angle, 0]) {
          arm_link(link1_len, 32, 22);
          translate([link1_len, 0, 22])
            rotate([0, 0, elbow_angle]) {
              arm_link(link2_len, 26, 18);
              translate([link2_len + 14, 0, 9])
                parallel_gripper();
            }
        }
    }
}

robot_arm();

